+    private boolean isPetOwnedBy(Owner owner, Pet pet) {
+        if (pet.getOwner() != null && pet.getOwner().getId() != null) {
+            return pet.getOwner().getId().equals(owner.getId());
+        }
+        return owner.getPet(pet.getId()) != null;
+    }
