+    private Owner ownerWithPet(int ownerId, int petId) {
+        Owner owner = ownerMapper.toOwner(owners.get(0));
+        PetDto pet = petMapper.toPetDto(petMapper.toPet(pets.get(0)));
+        pet.setId(petId);
+        owner.setPets(List.of(petMapper.toPet(pet)));
+        owner.getPet(petId).setOwner(owner);
+        return owner;
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testUpdateOwnersPetRejectsMismatchedOwnerWithoutSaving() throws Exception {
+        int ownerId = owners.get(1).getId();
+        int petId = pets.get(0).getId();
+        Owner otherOwner = ownerMapper.toOwner(owners.get(0));
+        given(this.clinicService.findOwnerById(ownerId)).willReturn(otherOwner);
+        org.springframework.samples.petclinic.model.Pet pet = petMapper.toPet(pets.get(0));
+        pet.setOwner(ownerMapper.toOwner(owners.get(2)));
+        given(this.clinicService.findPetById(petId)).willReturn(pet);
+        PetDto petDto = pets.get(0);
+        petDto.setName("Hijacked");
+        String body = new ObjectMapper().writeValueAsString(petDto);
+
+        this.mockMvc.perform(put("/api/owners/" + ownerId + "/pets/" + petId)
+                .contentType(MediaType.APPLICATION_JSON)
+                .content(body))
+            .andExpect(status().isNotFound());
+
+        org.mockito.Mockito.verify(this.clinicService, org.mockito.Mockito.never()).savePet(any());
+        org.assertj.core.api.Assertions.assertThat(pet.getName()).isNotEqualTo("Hijacked");
+        org.assertj.core.api.Assertions.assertThat(pet.getOwner().getId()).isEqualTo(owners.get(2).getId());
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testUpdateOwnersPetSetsOwnerOnSuccess() throws Exception {
+        int ownerId = owners.get(1).getId();
+        int petId = pets.get(0).getId();
+        Owner owner = ownerMapper.toOwner(owners.get(1));
+        given(this.clinicService.findOwnerById(ownerId)).willReturn(owner);
+        org.springframework.samples.petclinic.model.Pet pet = petMapper.toPet(pets.get(0));
+        pet.setOwner(owner);
+        given(this.clinicService.findPetById(petId)).willReturn(pet);
+        PetDto petDto = pets.get(0);
+        petDto.setName("Rex");
+        petDto.setBirthDate(LocalDate.of(2020, 1, 15));
+        String body = new ObjectMapper().writeValueAsString(petDto);
+
+        this.mockMvc.perform(put("/api/owners/" + ownerId + "/pets/" + petId)
+                .contentType(MediaType.APPLICATION_JSON)
+                .content(body))
+            .andExpect(status().isNoContent());
+
+        org.mockito.Mockito.verify(this.clinicService).savePet(any());
+        org.assertj.core.api.Assertions.assertThat(pet.getName()).isEqualTo("Rex");
+        org.assertj.core.api.Assertions.assertThat(pet.getOwner().getId()).isEqualTo(ownerId);
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testCreateVisitForMismatchedOwnerIsNotFoundAndNotSaved() throws Exception {
+        int ownerId = owners.get(1).getId();
+        int petId = pets.get(0).getId();
+        given(this.clinicService.findOwnerById(ownerId)).willReturn(ownerMapper.toOwner(owners.get(0)));
+        org.springframework.samples.petclinic.model.Pet pet = petMapper.toPet(pets.get(0));
+        pet.setOwner(ownerMapper.toOwner(owners.get(2)));
+        given(this.clinicService.findPetById(petId)).willReturn(pet);
+        VisitDto newVisit = visits.get(0);
+        newVisit.setId(999);
+        String body = new ObjectMapper().writeValueAsString(visitMapper.toVisit(newVisit));
+
+        this.mockMvc.perform(post("/api/owners/" + ownerId + "/pets/" + petId + "/visits")
+                .content(body).accept(MediaType.APPLICATION_JSON_VALUE).contentType(MediaType.APPLICATION_JSON_VALUE))
+            .andExpect(status().isNotFound());
+
+        org.mockito.Mockito.verify(this.clinicService, org.mockito.Mockito.never()).saveVisit(any());
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testCreateVisitForMissingOwnerIsNotFoundAndNotSaved() throws Exception {
+        given(this.clinicService.findOwnerById(99)).willReturn(null);
+        String body = new ObjectMapper().writeValueAsString(visitMapper.toVisit(visits.get(0)));
+
+        this.mockMvc.perform(post("/api/owners/99/pets/1/visits")
+                .content(body).accept(MediaType.APPLICATION_JSON_VALUE).contentType(MediaType.APPLICATION_JSON_VALUE))
+            .andExpect(status().isNotFound());
+
+        org.mockito.Mockito.verify(this.clinicService, org.mockito.Mockito.never()).saveVisit(any());
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testCreateVisitForMissingPetIsNotFoundAndNotSaved() throws Exception {
+        int ownerId = owners.get(0).getId();
+        given(this.clinicService.findOwnerById(ownerId)).willReturn(ownerWithPet(ownerId, 1));
+        given(this.clinicService.findPetById(42)).willReturn(null);
+        String body = new ObjectMapper().writeValueAsString(visitMapper.toVisit(visits.get(0)));
+
+        this.mockMvc.perform(post("/api/owners/" + ownerId + "/pets/42/visits")
+                .content(body).accept(MediaType.APPLICATION_JSON_VALUE).contentType(MediaType.APPLICATION_JSON_VALUE))
+            .andExpect(status().isNotFound());
+
+        org.mockito.Mockito.verify(this.clinicService, org.mockito.Mockito.never()).saveVisit(any());
+    }
+
+    @Test
+    @WithMockUser(roles = "OWNER_ADMIN")
+    void testCreateVisitForMatchingOwnerBindsRequestedPet() throws Exception {
+        int ownerId = owners.get(0).getId();
+        int petId = pets.get(0).getId();
+        Owner owner = ownerWithPet(ownerId, petId);
+        org.springframework.samples.petclinic.model.Pet pet = owner.getPet(petId);
+        given(this.clinicService.findOwnerById(ownerId)).willReturn(owner);
+        given(this.clinicService.findPetById(petId)).willReturn(pet);
+        VisitDto newVisit = visits.get(0);
+        newVisit.setId(null);
+        newVisit.setPetId(petId);
+        String body = new ObjectMapper().writeValueAsString(visitMapper.toVisit(newVisit));
+
+        this.mockMvc.perform(post("/api/owners/" + ownerId + "/pets/" + petId + "/visits")
+                .content(body).accept(MediaType.APPLICATION_JSON_VALUE).contentType(MediaType.APPLICATION_JSON_VALUE))
+            .andExpect(status().isCreated())
+            .andExpect(jsonPath("$.petId").value(petId));
+
+        org.mockito.ArgumentCaptor<org.springframework.samples.petclinic.model.Visit> captor =
+            org.mockito.ArgumentCaptor.forClass(org.springframework.samples.petclinic.model.Visit.class);
+        org.mockito.Mockito.verify(this.clinicService).saveVisit(captor.capture());
+        org.assertj.core.api.Assertions.assertThat(captor.getValue().getPet().getId()).isEqualTo(petId);
+    }
